/* D5 visual study. All data below is fictional and lives only in this page. */
const notes = [
  {id:'sources',title:'Sources et niveaux de confiance',collection:'method',date:'18 octobre',kind:'Note personnelle',summary:'Une source n’est utile que si sa provenance et ses limites restent visibles.',body:'<p>Avant de relier une information à une mission, conserver son origine, sa date et ce qu’elle permet vraiment de conclure. Une même affirmation peut dépendre de plusieurs sources qui ne se valent pas.</p><h3>Principes de lecture</h3><ul><li>Conserver le lien vers la source primaire quand il existe.</li><li>Séparer observation, interprétation et hypothèse.</li><li>Réexaminer les informations susceptibles de changer.</li></ul>',links:['questions','verification'],x:390,y:275},
  {id:'questions',title:'Questions ouvertes',collection:'northstar',date:'17 octobre',kind:'Note personnelle',summary:'Les incertitudes qui méritent une réponse avant toute décision.',body:'<p>Les questions ouvertes rendent visible ce qui reste inconnu. Elles évitent de transformer une intuition en certitude par simple répétition.</p><h3>À éclaircir</h3><ul><li>Quelles sources peuvent être lues localement ?</li><li>Quel niveau de preuve serait suffisant ?</li><li>Comment relier une conclusion à ses éléments de vérification ?</li></ul>',links:['sources','local'],x:205,y:165},
  {id:'local',title:'Recherche locale',collection:'northstar',date:'15 octobre',kind:'Note personnelle',summary:'Une piste de travail pour trouver des informations sans les transmettre.',body:'<p>Un index local peut rendre les notes et documents plus faciles à retrouver. Il faut mesurer la qualité des résultats, le coût de maintenance et les permissions nécessaires.</p><p>Voir aussi les <a href="#" data-note-link="questions">questions ouvertes</a> et les <a href="#" data-note-link="sources">sources et niveaux de confiance</a>.</p>',links:['questions','sources','verification'],x:245,y:410},
  {id:'verification',title:'Vérifier avant de conclure',collection:'method',date:'13 octobre',kind:'Note personnelle',summary:'Une conclusion doit rester reliée à la preuve qui l’appuie.',body:'<p>Définir des critères de vérification avant d’interpréter un résultat. Documenter les cas où le résultat est incomplet ou ambigu.</p><h3>Rappel</h3><p>Un résultat observé n’est pas nécessairement une mission acceptée.</p>',links:['sources','local','map'],x:565,y:390},
  {id:'map',title:'Carte du projet',collection:'northstar',date:'11 octobre',kind:'Note personnelle',summary:'Un point de départ pour les sujets liés au projet.',body:'<p>Cette carte rassemble les sujets, sans prétendre qu’ils sont déjà validés par Morgoth. Chaque note garde son auteur et sa provenance.</p><p>Commencer par <a href="#" data-note-link="verification">vérifier avant de conclure</a>.</p>',links:['verification'],x:635,y:165}
];
const byId = Object.fromEntries(notes.map(note=>[note.id,note]));
const state = {view:'home',note:'sources',collection:'all',graphFocus:'sources',local:false,zoom:1,panX:0,panY:0,dirty:false,brief:'research'};
const $ = (selector)=>document.querySelector(selector);
const $$ = (selector)=>Array.from(document.querySelectorAll(selector));

function confirmLeave(){return !state.dirty || window.confirm('Modifications non enregistrées dans cet aperçu. Quitter ce brief ?');}
function view(name,{force=false}={}){
  if(!force && name!==state.view && !confirmLeave()) return;
  if(name!==state.view) state.dirty=false;
  state.view=name;
  $$('.view').forEach(el=>el.classList.toggle('hidden',el.id!==`view-${name}`));
  $$('.nav-item[data-view]').forEach(el=>{const active=el.dataset.view===(name==='graph'?'notes':name);el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});
  if(name==='notes') renderNotes();
  if(name==='graph') renderGraph();
  document.title=`Morgoth · ${({home:'Accueil',missions:'Missions',notes:'Connaissances',graph:'Graphe',projects:'Projets',settings:'Réglages'})[name]} · aperçu D5`;
}
function selectNote(id,open=true){if(!byId[id])return;state.note=id;state.graphFocus=id;if(open)view('notes');else renderNotes();}
function renderNotes(){
  $('#all-note-count').textContent=String(notes.length);$('#northstar-note-count').textContent=String(notes.filter(n=>n.collection==='northstar').length);
  const filter=$('#note-filter').value.trim().toLocaleLowerCase('fr');
  const shown=notes.filter(n=>(state.collection==='all'||n.collection===state.collection)&&(n.title.toLocaleLowerCase('fr').includes(filter)||n.summary.toLocaleLowerCase('fr').includes(filter)));
  const list=$('#note-list');list.replaceChildren();
  for(const note of shown){const button=document.createElement('button');button.type='button';button.className=`list-item${state.note===note.id?' selected':''}`;button.innerHTML=`<strong></strong><small></small>`;button.querySelector('strong').textContent=note.title;button.querySelector('small').textContent=`${note.kind} · ${note.date}`;button.addEventListener('click',()=>selectNote(note.id,false));list.append(button)}
  if(!shown.length){const empty=document.createElement('p');empty.className='context-sub';empty.textContent='Aucune note dans cette sélection.';list.append(empty)}
  $$('.collection').forEach(button=>button.classList.toggle('selected',button.dataset.collection===state.collection));
  const note=byId[state.note];
  $('#note-reader').innerHTML=`<div class="note-meta"><span class="personal"></span><span>·</span><span class="note-date"></span><span>·</span><span>Aperçu fictif</span></div><h2></h2><div class="note-body"></div>`;
  $('#note-reader .personal').textContent=note.kind;$('#note-reader .note-date').textContent=`modifiée le ${note.date}`;$('#note-reader h2').textContent=note.title;$('#note-reader .note-body').innerHTML=note.body;
  const backlinks=notes.filter(other=>other.id!==note.id&&other.links.includes(note.id));
  const context=$('#note-context');context.replaceChildren();
  const heading=document.createElement('div');heading.className='context-heading';heading.textContent='Liens sortants';context.append(heading);
  for(const id of note.links)context.append(contextButton(id));
  const divider=document.createElement('div');divider.className='context-divider';context.append(divider);
  const backHeading=document.createElement('div');backHeading.className='context-heading';backHeading.textContent=`Rétroliens · ${backlinks.length}`;context.append(backHeading);
  for(const other of backlinks)context.append(contextButton(other.id));
  const source=document.createElement('p');source.className='context-sub';source.textContent='Liens de démonstration. Aucun index personnel ni backend connecté.';context.append(source);
}
function contextButton(id){const b=document.createElement('button');b.type='button';b.className='context-link';b.textContent=byId[id].title;b.addEventListener('click',()=>selectNote(id));return b}
function renderGraph(){
  const svg=$('#graph-svg');svg.replaceChildren();
  const focused=state.graphFocus, related=new Set([focused,...byId[focused].links,...notes.filter(n=>n.links.includes(focused)).map(n=>n.id)]);
  const filter=$('#graph-filter').value.trim().toLocaleLowerCase('fr');
  const visible=notes.filter(n=>(!state.local||related.has(n.id))&&(!filter||n.title.toLocaleLowerCase('fr').includes(filter)||related.has(n.id)));
  const visibleIds=new Set(visible.map(n=>n.id));
  const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.setAttribute('transform',`translate(${state.panX} ${state.panY}) scale(${state.zoom})`);svg.append(group);
  for(const note of visible){for(const linked of note.links){if(!visibleIds.has(linked)||notes.findIndex(n=>n.id===note.id)>notes.findIndex(n=>n.id===linked)&&byId[linked].links.includes(note.id))continue;const target=byId[linked];const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',note.x);line.setAttribute('y1',note.y);line.setAttribute('x2',target.x);line.setAttribute('y2',target.y);line.setAttribute('class',`graph-edge${related.has(note.id)&&related.has(linked)?'':' dim'}`);group.append(line)}}
  for(const note of visible){const node=document.createElementNS('http://www.w3.org/2000/svg','g');node.setAttribute('class',`graph-node${note.id===focused?' selected':''}${related.has(note.id)?'':' dim'}`);node.setAttribute('transform',`translate(${note.x} ${note.y})`);node.setAttribute('role','button');node.setAttribute('tabindex','0');node.setAttribute('aria-label',`Sélectionner ${note.title}`);const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.setAttribute('r',note.id===focused?'12':'9');const label=document.createElementNS('http://www.w3.org/2000/svg','text');label.setAttribute('y','30');label.textContent=note.title;node.append(circle,label);node.addEventListener('click',()=>focusNode(note.id));node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();focusNode(note.id)}});group.append(node)}
  const help=document.createElement('div');help.className='graph-help';help.textContent='Glisser pour déplacer · molette pour zoomer';$('#graph-canvas .graph-help')?.remove();$('#graph-canvas').append(help);
  $('#graph-local').setAttribute('aria-pressed',String(state.local));$('#graph-local').textContent=state.local?'Graphe local ✓':'Graphe local';
  const info=$('#graph-inspector');info.replaceChildren();const h=document.createElement('div');h.className='aside-label';h.textContent='Note sélectionnée';info.append(h);const title=document.createElement('h2');title.textContent=byId[focused].title;info.append(title);const p=document.createElement('p');p.textContent=byId[focused].summary;info.append(p);const open=document.createElement('button');open.className='text-link';open.textContent='Ouvrir la note →';open.addEventListener('click',()=>selectNote(focused));info.append(open);const divider=document.createElement('div');divider.className='context-divider';info.append(divider);const l=document.createElement('div');l.className='context-heading';l.textContent='Parcourir sans graphe';info.append(l);for(const note of visible)info.append(contextButtonForGraph(note.id));
}
function contextButtonForGraph(id){const b=document.createElement('button');b.type='button';b.className='context-link';b.textContent=byId[id].title;b.addEventListener('click',()=>focusNode(id));return b}
function focusNode(id){state.graphFocus=id;renderGraph()}
function setZoom(value){state.zoom=Math.max(.65,Math.min(1.75,value));renderGraph()}
const paletteItems=[{label:'Accueil',view:'home',type:'Espace'},{label:'Missions',view:'missions',type:'Espace'},{label:'Connaissances · Notes',view:'notes',type:'Espace'},{label:'Connaissances · Graphe',view:'graph',type:'Espace'},{label:'Projets',view:'projects',type:'Espace'},{label:'Réglages',view:'settings',type:'Espace'},{label:'Nouveau brief local',view:'missions',new:'brief',type:'Action de l’aperçu'},{label:'Nouvelle note locale',view:'notes',new:'note',type:'Action de l’aperçu'},...notes.map(n=>({label:n.title,view:'notes',note:n.id,type:'Note fictive'}))];
function openPalette(){const dialog=$('#palette');dialog.showModal();$('#palette-input').value='';renderPalette();$('#palette-input').focus()}
function renderPalette(){const input=$('#palette-input').value.trim().toLocaleLowerCase('fr');const results=$('#palette-results');results.replaceChildren();for(const item of paletteItems.filter(i=>i.label.toLocaleLowerCase('fr').includes(input)).slice(0,9)){const b=document.createElement('button');b.type='button';b.className='palette-result';b.innerHTML='<span></span><small></small>';b.querySelector('span').textContent=item.label;b.querySelector('small').textContent=item.type;b.addEventListener('click',()=>{if(item.note)state.note=item.note;view(item.view);$('#palette').close();if(item.new==='brief')newBrief();if(item.new==='note')newNote()});results.append(b)}if(!results.childElementCount){const p=document.createElement('p');p.className='context-sub';p.textContent='Aucun résultat dans les données de démonstration.';results.append(p)}}
function newNote(){if(!byId['new-note']){const note={id:'new-note',title:'Nouvelle note',collection:'northstar',date:'à l’instant',kind:'Ébauche fictive non enregistrée',summary:'Contenu de démonstration, perdu à la fermeture de cet aperçu.',body:'<p>Cette note est un aperçu local. Rien n’est enregistré.</p><label class="sr-only" for="new-note-body">Texte de la nouvelle note</label><textarea id="new-note-body" rows="7" placeholder="Écrivez une idée…"></textarea>',links:[],x:440,y:95};notes.unshift(note);byId[note.id]=note;}state.note='new-note';renderNotes();$('#new-note-body')?.focus()}
function newBrief(){state.brief='new';$('#brief-title').value='';$('#brief-objective').value='';$('#brief-criteria').value='';$('#brief-feedback').textContent='Nouveau brief fictif · non enregistré';$('.soft-state').textContent='Brouillon fictif · non soumis';$('#brief-title').focus()}
function loadBrief(id){if(!confirmLeave())return;state.brief=id;state.dirty=false;$$('[data-brief]').forEach(b=>b.classList.toggle('selected',b.dataset.brief===id));const title=$('#brief-title'),objective=$('#brief-objective'),criteria=$('#brief-criteria');const historical=id==='history';title.readOnly=historical;objective.readOnly=historical;criteria.readOnly=historical;$('#brief-save').disabled=historical;$('#brief-cancel').disabled=historical;if(historical){title.value='Revue de sources publiques';objective.value='Checkpoint historique du registre de test. Dans le produit, ce contenu proviendra uniquement de la lecture Project-scopée.';criteria.value='État enregistré dans le registre expérimental, jamais un état d’exécution en direct.';$('.soft-state').textContent='Historique de test · lecture seule'}else{title.value=id==='outline'?'Clarifier le périmètre du projet':'Étudier les options de recherche locale';objective.value=id==='outline'?'Définir ce qui appartient au contexte Northstar et ce qui doit rester hors du périmètre.':'Comparer les options de recherche locale pour retrouver rapidement des notes et des documents personnels. Décrire les compromis de confidentialité, de qualité des résultats et de maintenance.';criteria.value=id==='outline'?'Le périmètre est explicite et chaque exclusion est expliquée.':'Une comparaison sourcée couvre au moins deux approches. Chaque recommandation mentionne ses hypothèses et ses limites.';$('.soft-state').textContent='Brouillon local · non soumis'}$('#brief-feedback').textContent='Aperçu uniquement · aucune sauvegarde réelle'}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.note)state.note=b.dataset.note;view(b.dataset.view);if(b.dataset.new==='brief')newBrief();if(b.dataset.new==='note')newNote()}));
$('#collapse').addEventListener('click',()=>$('#shell').classList.toggle('collapsed'));
$('.brand-mark').addEventListener('click',()=>$('#shell').classList.remove('collapsed'));
$('#note-filter').addEventListener('input',renderNotes);$$('[data-collection]').forEach(b=>b.addEventListener('click',()=>{state.collection=b.dataset.collection;renderNotes()}));
$('#note-reader').addEventListener('click',e=>{const a=e.target.closest('[data-note-link]');if(a){e.preventDefault();selectNote(a.dataset.noteLink)}});
$('#new-brief').addEventListener('click',newBrief);$$('[data-brief]').forEach(b=>b.addEventListener('click',()=>loadBrief(b.dataset.brief)));
['brief-title','brief-objective','brief-criteria'].forEach(id=>$('#'+id).addEventListener('input',()=>{state.dirty=true;$('#brief-feedback').textContent='Modifications dans cet aperçu · non enregistrées'}));
$('#brief-cancel').addEventListener('click',()=>loadBrief(state.brief==='new'?'research':state.brief));
$('#brief-save').addEventListener('click',()=>{$('#brief-feedback').textContent='Simulation seulement · aucune donnée enregistrée';state.dirty=false});
$('#mission-filter').addEventListener('input',e=>{$$('[data-brief]').forEach(b=>b.hidden=!b.textContent.toLocaleLowerCase('fr').includes(e.target.value.toLocaleLowerCase('fr')))});
$('#graph-local').addEventListener('click',()=>{state.local=!state.local;renderGraph()});$('#graph-reset').addEventListener('click',()=>{state.local=false;state.zoom=1;state.panX=0;state.panY=0;$('#graph-filter').value='';renderGraph()});$('#graph-filter').addEventListener('input',renderGraph);$('#zoom-in').addEventListener('click',()=>setZoom(state.zoom+.15));$('#zoom-out').addEventListener('click',()=>setZoom(state.zoom-.15));
$('#graph-svg').addEventListener('wheel',e=>{e.preventDefault();setZoom(state.zoom+(e.deltaY<0?.1:-.1))},{passive:false});let pointer=null;$('#graph-svg').addEventListener('pointerdown',e=>{if(e.target.closest('.graph-node'))return;pointer={x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.classList.add('dragging')});$('#graph-svg').addEventListener('pointermove',e=>{if(!pointer)return;const rect=e.currentTarget.getBoundingClientRect();state.panX+=(e.clientX-pointer.x)*840/rect.width;state.panY+=(e.clientY-pointer.y)*590/rect.height;pointer={x:e.clientX,y:e.clientY};renderGraph()});$('#graph-svg').addEventListener('pointerup',e=>{pointer=null;e.currentTarget.classList.remove('dragging')});
$('#search-launch').addEventListener('click',openPalette);$('#palette-close').addEventListener('click',()=>$('#palette').close());$('#palette-input').addEventListener('input',renderPalette);$('#palette-input').addEventListener('keydown',e=>{if(e.key==='Enter')$('#palette-results .palette-result')?.click()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}});
renderNotes();
const previewView=new URLSearchParams(location.search).get('view');
if(['home','missions','notes','graph','projects','settings'].includes(previewView)) view(previewView);
